```python
import sys

import pygame

from settings import WIDTH, HUD, CELL, ROWS, FPS, DIFFICULTIES, COLORS
from snake import Snake
from food import Food

MENU, PLAYING, GAME_OVER = "menu", "playing", "game_over"


class Game:
    def __init__(self):
        pygame.init()
        self.screen = pygame.display.set_mode((WIDTH, ROWS * CELL + HUD))
        pygame.display.set_caption("Snake")
        self.clock = pygame.time.Clock()
        self.font = pygame.font.SysFont(None, 26)
        self.big_font = pygame.font.SysFont(None, 52)
        self.state = MENU
        self.diff_name, self.speed = DIFFICULTIES["2"]
        self.snake = Snake()
        self.food = Food(self.snake)
        self.score = 0
        self.acc = 0.0

    def run(self):
        while True:
            dt = self.clock.tick(FPS) / 1000.0
            self.handle_events()
            if self.state == PLAYING:
                self.acc += dt
                step_time = 1.0 / self.speed
                while self.acc >= step_time:
                    self.acc -= step_time
                    self.update()
            self.draw()
            pygame.display.flip()

    def handle_events(self):
        for event in pygame.event.get():
            if event.type == pygame.QUIT:
                self.quit()
            elif event.type == pygame.KEYDOWN:
                self.on_key(event.key)

    @staticmethod
    def quit():
        pygame.quit()
        sys.exit()

    def on_key(self, key):
        directions = {
            pygame.K_UP: (0, -1), pygame.K_w: (0, -1),
            pygame.K_DOWN: (0, 1), pygame.K_s: (0, 1),
            pygame.K_LEFT: (-1, 0), pygame.K_a: (-1, 0),
            pygame.K_RIGHT: (1, 0), pygame.K_d: (1, 0),
        }
        if self.state == MENU:
            if key in (pygame.K_1, pygame.K_2, pygame.K_3, pygame.K_4):
                self.diff_name, self.speed = DIFFICULTIES[str(key - pygame.K_1 + 1)]
                self.start()
            elif key == pygame.K_ESCAPE:
                self.quit()
        elif self.state == PLAYING:
            if key in directions:
                self.snake.set_direction(directions[key])
            elif key == pygame.K_ESCAPE:
                self.state = MENU
        else:
            if key in (pygame.K_SPACE, pygame.K_RETURN):
                self.state = MENU
            elif key == pygame.K_ESCAPE:
                self.quit()

    def start(self):
        self.snake.reset()
        self.food.respawn(self.snake)
        self.score = 0
        self.acc = 0.0
        self.state = PLAYING

    def update(self):
        self.snake.step()
        if self.snake.hits_wall() or self.snake.hits_self():
            self.state = GAME_OVER
            return
        if self.food.pos is not None and self.snake.body[0] == self.food.pos:
            self.score += 1
            self.snake.grow_pending += 1
            self.food.respawn(self.snake)
            if self.food.pos is None:
                self.state = GAME_OVER

    def draw(self):
        self.screen.fill(COLORS["bg"])
        if self.state == MENU:
            self.draw_menu()
        else:
            self.draw_board()
            if self.state == GAME_OVER:
                self.draw_game_over()

    @staticmethod
    def cell_rect(x, y, inset=1):
        return pygame.Rect(x * CELL + inset, HUD + y * CELL + inset,
                           CELL - 2 * inset, CELL - 2 * inset)

    def draw_board(self):
        pygame.draw.rect(self.screen, COLORS["border"], (0, HUD, WIDTH, ROWS * CELL), 2)
        if self.food.pos is not None:
            pygame.draw.rect(self.screen, COLORS["food"],
                             self.cell_rect(*self.food.pos, inset=3), border_radius=4)
        for i, (x, y) in enumerate(self.snake.body):
            color = COLORS["head"] if i == 0 else COLORS["snake"]
            pygame.draw.rect(self.screen, color, self.cell_rect(x, y), border_radius=3)
        info = f"Score: {self.score}   Length: {len(self.snake.body)}   Mode: {self.diff_name}"
        self.screen.blit(self.font.render(info, True, COLORS["text"]), (10, 10))

    def draw_menu(self):
        title = self.big_font.render("SNAKE", True, COLORS["head"])
        self.screen.blit(title, (WIDTH // 2 - title.get_width() // 2, 60))
        lines = ["Select difficulty (press 1-4):"]
        lines += [f"  {k}. {name} - {speed} cells/sec"
                  for k, (name, speed) in sorted(DIFFICULTIES.items())]
        lines += ["", "Move: Arrow keys or WASD", "Esc: quit"]
        for i, line in enumerate(lines):
            surf = self.font.render(line, True, COLORS["text"])
            self.screen.blit(surf, (WIDTH // 2 - surf.get_width() // 2, 150 + i * 30))

    def draw_game_over(self):
        overlay = pygame.Surface((WIDTH, ROWS * CELL + HUD), pygame.SRCALPHA)
        overlay.fill((0, 0, 0, 170))
        self.screen.blit(overlay, (0, 0))
        center_y = (ROWS * CELL + HUD) // 2 - 60
        texts = [
            (self.big_font.render("GAME OVER", True, COLORS["food"]), 0),
            (self.font.render(f"Final score: {self.score}", True, COLORS["text"]), 70),
            (self.font.render("Space/Enter: menu   Esc: quit", True, COLORS["text"]), 110),
        ]
        for surf, dy in texts:
            self.screen.blit(surf, (WIDTH // 2 - surf.get_width() // 2, center_y + dy))
